-- 0146 (19 Nov 2026, APPLIED LIVE: additive): under-18 check from faces (AWS Rekognition DetectFaces AGE_RANGE).
-- One row per member: the most cautious reading of the card photo and the latest face-check selfie.
-- verdict: LIKELY_MINOR = AWS top of range < 20 · CHECK = bottom < 18 and top < 24 · OK · NO_FACE.
-- AWS reads filtered / beauty-mode card photos young: a reading is a reason to look, never proof. Nothing here closes or changes an account.
create table if not exists public.kr8_age_checks (
  user_id    uuid primary key references auth.users(id) on delete cascade,
  member_no  int,
  low        int,
  high       int,
  source     text,          -- card | selfie | check (0147 auto, the straight face-check frame)
  verdict    text not null check (verdict in ('LIKELY_MINOR','CHECK','OK','NO_FACE')),
  readings   jsonb not null default '{}'::jsonb,   -- {card: {Low, High}, selfie: {Low, High}}
  checked_at timestamptz not null default now()
);
alter table public.kr8_age_checks enable row level security;
revoke all on public.kr8_age_checks from anon, authenticated;

insert into public.kr8_age_checks (user_id, member_no, low, high, source, verdict, readings)
select x.user_id, x.member_no, x.low, x.high, x.source, x.verdict, coalesce(x.readings, '{}'::jsonb)
